+#!/usr/bin/env node
+
+import { Command } from 'commander';
+import { buildSite } from './index';
+
+interface CliOptions {
+  content: string;
+  output: string;
+}
+
+const program = new Command();
+
+program
+  .name('ssg')
+  .description('Generate a static HTML site from Markdown files')
+  .command('build')
