+    await fs.writeFile(path.join(contentDir, 'about.md'), '---\ntags: company, team\n---\nAbout us');
+
+    const [page] = await buildSite({ contentDir, outputDir });
+
+    expect(page).toMatchObject({ title: 'about', tags: ['company', 'team'] });
